import {
  BufferTarget,
  CanvasSource,
  getFirstEncodableVideoCodec,
  Output,
  Quality,
  WebMOutputFormat,
  type VideoCodec,
} from "mediabunny";
import type { EvaluatedFrame } from "../core/frameEvaluator";
import { renderFrame } from "../core/renderer";
import type { DisplayMode } from "../shared/sceneSchema";

// VP9 keeps the quality/size balance the previous MediaRecorder path had; VP8
// stays available for leaner WebCodecs implementations that reject VP9.
const kCodecCandidates: VideoCodec[] = ["vp9", "vp8"];
const kQuality = new Quality("high");
// Frequent key frames cost size but keep scrubbing responsive, which matters
// more for short preview clips than for long-form video.
const kKeyFrameIntervalSeconds = 1;

// Encodes evaluated frames into a WebM blob through WebCodecs. Frames are
// rendered onto an offscreen canvas at the scene's native pixel size, so the
// output resolution is independent of the preview panel size and zoom.
//
// Unlike a MediaRecorder capture this is not bound to wall-clock time:
// timestamps come from the frame index, so the caller may push frames as fast
// as it can evaluate them and the result still plays at the scene frame rate.
export class VideoRecorder {
  private readonly context: CanvasRenderingContext2D;
  private readonly output: Output<WebMOutputFormat, BufferTarget>;
  private readonly source: CanvasSource;
  private readonly frameDurationSeconds: number;
  private encodedFrameCount = 0;

  static isSupported(): boolean {
    return typeof VideoEncoder !== "undefined" && typeof VideoFrame !== "undefined";
  }

  // Async because codec support and the output header can only be resolved by
  // querying the browser's encoder.
  static async create(
    canvasWidth: number,
    canvasHeight: number,
    fps: number,
  ): Promise<VideoRecorder> {
    if (!VideoRecorder.isSupported()) {
      throw new Error("WebM recording requires WebCodecs support");
    }
    const width = Math.max(Math.round(canvasWidth), 1);
    const height = Math.max(Math.round(canvasHeight), 1);
    const frameRate = Math.max(fps, 0.001);
    const codec = await getFirstEncodableVideoCodec(kCodecCandidates, {
      width,
      height,
      quality: kQuality,
    });
    if (codec === null) {
      throw new Error("no supported WebM video codec is available");
    }
    const recorder = new VideoRecorder(width, height, frameRate, codec);
    await recorder.output.start();
    return recorder;
  }

  private constructor(width: number, height: number, frameRate: number, codec: VideoCodec) {
    this.frameDurationSeconds = 1 / frameRate;
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d");
    if (context === null) {
      throw new Error("2D canvas context unavailable for recording");
    }
    this.context = context;
    this.output = new Output({
      format: new WebMOutputFormat(),
      target: new BufferTarget(),
    });
    this.source = new CanvasSource(canvas, {
      codec,
      quality: kQuality,
      keyFrameInterval: kKeyFrameIntervalSeconds,
    });
    this.output.addVideoTrack(this.source, { frameRate });
  }

  // Renders and encodes one frame. Awaiting the returned promise applies the
  // encoder's own backpressure, so the queue cannot grow without bound.
  async captureFrame(
    frame: EvaluatedFrame,
    displayMode: DisplayMode,
    showIndexLabels: boolean,
  ): Promise<void> {
    renderFrame(this.context, frame, 1, { displayMode, showIndexLabels });
    const timestamp = this.encodedFrameCount * this.frameDurationSeconds;
    this.encodedFrameCount += 1;
    await this.source.add(timestamp, this.frameDurationSeconds);
  }

  async stop(): Promise<Blob> {
    await this.output.finalize();
    const buffer = this.output.target.buffer;
    if (buffer === null) {
      throw new Error("recording produced no data");
    }
    return new Blob([buffer], { type: this.output.format.mimeType });
  }

  // Releases encoder resources without producing a file, for aborted runs.
  async dispose(): Promise<void> {
    if (this.output.state !== "finalized" && this.output.state !== "canceled") {
      await this.output.cancel();
    }
  }
}
